#!/usr/bin/env python3\n\"\"\"\nEnhanced Nexus Prime Seed Data Script\nGenerates realistic incident scenarios for testing the complete system\n\"\"\"\n\nimport asyncio\nimport json\nimport random\nfrom datetime import datetime, timedelta\nfrom typing import List, Dict, Any\n\n# Realistic incident scenarios\nINCIDENT_SCENARIOS = [\n    {\n        \"title\": \"Payment Gateway Timeout Spike\",\n        \"summary\": \"P99 latency exceeded 5000ms on payment processing. Transaction failure rate at 12%. Customer complaints increasing.\",\n        \"severity\": \"SEV1\",\n        \"source\": \"datadog\",\n        \"tags\": [\"payment\", \"latency\", \"customer-impact\", \"revenue\"]\n    },\n    {\n        \"title\": \"Database Connection Pool Exhaustion\",\n        \"summary\": \"Primary database connection pool at 98% utilization. Query timeouts detected across multiple services.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"prometheus\",\n        \"tags\": [\"database\", \"performance\", \"connection-pool\"]\n    },\n    {\n        \"title\": \"CDN Cache Miss Rate Anomaly\",\n        \"summary\": \"CDN cache miss rate jumped from 5% to 45%. Origin server load increased 8x. Page load times degraded.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"generic\",\n        \"tags\": [\"cdn\", \"performance\", \"cache\", \"frontend\"]\n    },\n    {\n        \"title\": \"Authentication Service Memory Leak\",\n        \"summary\": \"Auth service memory usage at 95%. Response times degraded. Login failures increasing.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"pagerduty\",\n        \"tags\": [\"auth\", \"memory\", \"performance\", \"login\"]\n    },\n    {\n        \"title\": \"Kubernetes Node Disk Space Critical\",\n        \"summary\": \"Production k8s node disk usage at 92%. Pod evictions starting. Service disruption imminent.\",\n        \"severity\": \"SEV1\",\n        \"source\": \"prometheus\",\n        \"tags\": [\"kubernetes\", \"disk\", \"infrastructure\", \"critical\"]\n    },\n    {\n        \"title\": \"API Rate Limiting False Positives\",\n        \"summary\": \"Rate limiter blocking legitimate traffic. 15% of API requests rejected. Customer API integrations failing.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"datadog\",\n        \"tags\": [\"api\", \"rate-limiting\", \"false-positive\", \"integration\"]\n    },\n    {\n        \"title\": \"Message Queue Lag Spike\",\n        \"summary\": \"Kafka consumer lag exceeded 10M messages. Order processing delayed by 45 minutes. Customer notifications delayed.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"prometheus\",\n        \"tags\": [\"kafka\", \"messaging\", \"lag\", \"orders\"]\n    },\n    {\n        \"title\": \"SSL Certificate Expiration Alert\",\n        \"summary\": \"Primary domain SSL certificate expires in 3 days. Automated renewal failed. Manual intervention required.\",\n        \"severity\": \"SEV3\",\n        \"source\": \"generic\",\n        \"tags\": [\"ssl\", \"certificate\", \"security\", \"expiration\"]\n    },\n    {\n        \"title\": \"Search Service Index Corruption\",\n        \"summary\": \"Elasticsearch index corruption detected. Search results incomplete. Product discovery impacted.\",\n        \"severity\": \"SEV2\",\n        \"source\": \"pagerduty\",\n        \"tags\": [\"elasticsearch\", \"search\", \"corruption\", \"product\"]\n    },\n    {\n        \"title\": \"Load Balancer Health Check Failures\",\n        \"summary\": \"3 out of 8 backend servers failing health checks. Traffic routing to remaining servers. Capacity reduced.\",\n        \"severity\": \"SEV3\",\n        \"source\": \"datadog\",\n        \"tags\": [\"load-balancer\", \"health-check\", \"capacity\", \"backend\"]\n    }\n]\n\nWEBHOOK_ENDPOINTS = {\n    \"datadog\": \"http://localhost:8000/api/v1/ingest/webhook/datadog\",\n    \"pagerduty\": \"http://localhost:8000/api/v1/ingest/webhook/pagerduty\",\n    \"prometheus\": \"http://localhost:8000/api/v1/ingest/webhook/prometheus\",\n    \"generic\": \"http://localhost:8000/api/v1/ingest/webhook/generic\"\n}\n\ndef create_datadog_payload(scenario: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Create Datadog-style webhook payload\"\"\"\n    return {\n        \"title\": scenario[\"title\"],\n        \"body\": scenario[\"summary\"],\n        \"alert_type\": \"error\" if scenario[\"severity\"] in [\"SEV1\", \"SEV2\"] else \"warning\",\n        \"tags\": scenario[\"tags\"],\n        \"priority\": \"high\" if scenario[\"severity\"] == \"SEV1\" else \"normal\",\n        \"source_type_name\": \"datadog\",\n        \"date_happened\": int(datetime.utcnow().timestamp()),\n        \"aggregation_key\": f\"incident_{random.randint(1000, 9999)}\",\n        \"alert_id\": random.randint(100000, 999999)\n    }\n\ndef create_pagerduty_payload(scenario: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Create PagerDuty-style webhook payload\"\"\"\n    return {\n        \"messages\": [{\n            \"event\": \"incident.trigger\",\n            \"log_entries\": [{\n                \"type\": \"trigger_log_entry\",\n                \"created_at\": datetime.utcnow().isoformat() + \"Z\",\n                \"summary\": scenario[\"title\"]\n            }],\n            \"incident\": {\n                \"id\": f\"PD{random.randint(10000, 99999)}\",\n                \"incident_number\": random.randint(1000, 9999),\n                \"title\": scenario[\"title\"],\n                \"description\": scenario[\"summary\"],\n                \"created_at\": datetime.utcnow().isoformat() + \"Z\",\n                \"status\": \"triggered\",\n                \"urgency\": \"high\" if scenario[\"severity\"] == \"SEV1\" else \"low\",\n                \"service\": {\n                    \"name\": random.choice([\"Payment Service\", \"Auth Service\", \"API Gateway\", \"Database Cluster\"]),\n                    \"summary\": \"Production Service\"\n                },\n                \"assignments\": [{\n                    \"assignee\": {\n                        \"summary\": \"On-Call Engineer\",\n                        \"type\": \"user\"\n                    }\n                }]\n            }\n        }]\n    }\n\ndef create_prometheus_payload(scenario: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Create Prometheus AlertManager-style webhook payload\"\"\"\n    return {\n        \"version\": \"4\",\n        \"groupKey\": f\"group_{random.randint(1000, 9999)}\",\n        \"status\": \"firing\",\n        \"receiver\": \"nexus-prime\",\n        \"groupLabels\": {\n            \"alertname\": scenario[\"title\"].replace(\" \", \"_\").lower()\n        },\n        \"commonLabels\": {\n            \"alertname\": scenario[\"title\"].replace(\" \", \"_\").lower(),\n            \"severity\": scenario[\"severity\"].lower(),\n            \"instance\": f\"prod-{random.choice(['web', 'api', 'db', 'cache'])}-{random.randint(1, 5)}\"\n        },\n        \"commonAnnotations\": {\n            \"description\": scenario[\"summary\"],\n            \"summary\": scenario[\"title\"]\n        },\n        \"externalURL\": \"http://prometheus.local:9093\",\n        \"alerts\": [{\n            \"status\": \"firing\",\n            \"labels\": {\n                \"alertname\": scenario[\"title\"].replace(\" \", \"_\").lower(),\n                \"severity\": scenario[\"severity\"].lower(),\n                \"instance\": f\"prod-{random.choice(['web', 'api', 'db', 'cache'])}-{random.randint(1, 5)}\",\n                \"job\": random.choice([\"api-server\", \"web-server\", \"database\", \"cache\"])\n            },\n            \"annotations\": {\n                \"description\": scenario[\"summary\"],\n                \"summary\": scenario[\"title\"]\n            },\n            \"startsAt\": datetime.utcnow().isoformat() + \"Z\",\n            \"endsAt\": \"0001-01-01T00:00:00Z\",\n            \"generatorURL\": f\"http://prometheus.local:9090/graph?g0.expr=up%7Bjob%3D%22{random.choice(['api', 'web', 'db'])}%22%7D&g0.tab=1\",\n            \"fingerprint\": f\"{random.randint(1000000000, 9999999999)}\"\n        }]\n    }\n\ndef create_generic_payload(scenario: Dict[str, Any]) -> Dict[str, Any]:\n    \"\"\"Create generic webhook payload\"\"\"\n    return {\n        \"title\": scenario[\"title\"],\n        \"message\": scenario[\"summary\"],\n        \"severity\": scenario[\"severity\"].lower(),\n        \"source\": \"monitoring\",\n        \"timestamp\": datetime.utcnow().isoformat(),\n        \"tags\": scenario[\"tags\"],\n        \"metadata\": {\n            \"environment\": \"production\",\n            \"region\": random.choice([\"us-east-1\", \"us-west-2\", \"eu-west-1\"]),\n            \"service\": random.choice([\"payment-api\", \"user-service\", \"order-processor\", \"notification-service\"]),\n            \"version\": f\"v{random.randint(1, 3)}.{random.randint(0, 9)}.{random.randint(0, 9)}\"\n        }\n    }\n\nasync def send_incident(scenario: Dict[str, Any]) -> bool:\n    \"\"\"Send incident to appropriate webhook endpoint\"\"\"\n    import aiohttp\n    \n    source = scenario[\"source\"]\n    endpoint = WEBHOOK_ENDPOINTS[source]\n    \n    # Create appropriate payload based on source\n    if source == \"datadog\":\n        payload = create_datadog_payload(scenario)\n    elif source == \"pagerduty\":\n        payload = create_pagerduty_payload(scenario)\n    elif source == \"prometheus\":\n        payload = create_prometheus_payload(scenario)\n    else:\n        payload = create_generic_payload(scenario)\n    \n    try:\n        async with aiohttp.ClientSession() as session:\n            async with session.post(\n                endpoint,\n                json=payload,\n                headers={\"Content-Type\": \"application/json\"}\n            ) as response:\n                if response.status == 200:\n                    result = await response.json()\n                    print(f\"✅ {scenario['severity']} Incident Created: {scenario['title']}\")\n                    print(f\"   ID: {result.get('incident_id', 'Unknown')}\")\n                    print(f\"   Source: {source.upper()}\")\n                    print(f\"   Payload size: {len(json.dumps(payload))} bytes\")\n                    return True\n                else:\n                    print(f\"❌ Failed to create incident: {response.status}\")\n                    return False\n    except Exception as e:\n        print(f\"❌ Error sending incident: {e}\")\n        return False\n\nasync def create_incident_wave(scenarios: List[Dict[str, Any]], delay_range: tuple = (5, 15)):\n    \"\"\"Create a wave of incidents with realistic timing\"\"\"\n    print(f\"\\n🌊 Creating incident wave with {len(scenarios)} incidents...\")\n    \n    success_count = 0\n    for i, scenario in enumerate(scenarios):\n        print(f\"\\n📊 Creating incident {i+1}/{len(scenarios)}...\")\n        \n        success = await send_incident(scenario)\n        if success:\n            success_count += 1\n        \n        # Add realistic delay between incidents\n        if i < len(scenarios) - 1:\n            delay = random.randint(*delay_range)\n            print(f\"⏳ Waiting {delay} seconds before next incident...\")\n            await asyncio.sleep(delay)\n    \n    print(f\"\\n📈 Wave complete: {success_count}/{len(scenarios)} incidents created successfully\")\n    return success_count\n\nasync def simulate_realistic_scenario():\n    \"\"\"Simulate a realistic incident scenario over time\"\"\"\n    print(\"🚀 Starting Nexus Prime Realistic Incident Simulation\")\n    print(\"=\" * 60)\n    \n    # Shuffle scenarios for realistic randomness\n    scenarios = INCIDENT_SCENARIOS.copy()\n    random.shuffle(scenarios)\n    \n    # Create initial wave of incidents\n    initial_wave = scenarios[:3]  # Start with 3 critical incidents\n    await create_incident_wave(initial_wave, delay_range=(10, 20))\n    \n    print(\"\\n⏸️  Pausing for 30 seconds to let AI analysis complete...\")\n    await asyncio.sleep(30)\n    \n    # Create follow-up incidents\n    followup_wave = scenarios[3:6]  # Add 3 more incidents\n    await create_incident_wave(followup_wave, delay_range=(15, 25))\n    \n    print(\"\\n⏸️  Pausing for 45 seconds to observe remediation pipeline...\")\n    await asyncio.sleep(45)\n    \n    # Create final wave\n    final_wave = scenarios[6:8]  # Add 2 final incidents\n    await create_incident_wave(final_wave, delay_range=(20, 30))\n    \n    print(\"\\n🎯 Simulation Complete!\")\n    print(\"\\n📊 Summary:\")\n    print(f\"   • Total incidents: {len(scenarios[:8])}\")\n    print(f\"   • SEV1 incidents: {len([s for s in scenarios[:8] if s['severity'] == 'SEV1'])}\")\n    print(f\"   • SEV2 incidents: {len([s for s in scenarios[:8] if s['severity'] == 'SEV2'])}\")\n    print(f\"   • SEV3 incidents: {len([s for s in scenarios[:8] if s['severity'] == 'SEV3'])}\")\n    print(\"\\n🔍 Check the dashboard at http://localhost:3000 to see real-time updates!\")\n    print(\"📧 Check console logs for notification simulations (Slack, Email, SMS, Telegram)\")\n    print(\"🔄 Watch incidents progress through: OPEN → INVESTIGATING → MITIGATED → RESOLVED\")\n\nasync def create_single_critical_incident():\n    \"\"\"Create a single critical incident for quick testing\"\"\"\n    critical_scenarios = [s for s in INCIDENT_SCENARIOS if s[\"severity\"] == \"SEV1\"]\n    scenario = random.choice(critical_scenarios)\n    \n    print(\"🚨 Creating CRITICAL incident for immediate testing...\")\n    success = await send_incident(scenario)\n    \n    if success:\n        print(\"\\n✅ Critical incident created successfully!\")\n        print(\"🔍 Check dashboard for real-time updates\")\n        print(\"📧 Watch console for notification simulations\")\n        print(\"⏳ AI analysis will complete in ~30 seconds\")\n        print(\"🔄 Remediation pipeline will start automatically\")\n    else:\n        print(\"❌ Failed to create critical incident\")\n\nif __name__ == \"__main__\":\n    import sys\n    \n    if len(sys.argv) > 1 and sys.argv[1] == \"--quick\":\n        # Quick mode: create single critical incident\n        asyncio.run(create_single_critical_incident())\n    else:\n        # Full simulation mode\n        asyncio.run(simulate_realistic_scenario())\n